import { expect, test, uniqueName } from "../../fixtures";

test.describe("vendor names are unique within a tenant", () => {
  test(
    "creating a vendor whose name differs only by case is rejected with vendor_name_taken",
    { tag: "@VEN-03" },
    async ({ apiAs }) => {
      // Arrange: an existing vendor in the member's tenant.
      const member = await apiAs("member");
      const existingName = uniqueName("Acme Freight");
      const existing = await member.post("/api/vendors", {
        data: {
          name: existingName,
          category: "logistics",
          contact_email: "ops@acmefreight.example",
        },
      });
      expect(existing.status()).toBe(201);

      // Act: create a vendor with the same name in lowercase.
      const duplicate = await member.post("/api/vendors", {
        data: {
          name: existingName.toLowerCase(),
          category: "logistics",
          contact_email: "ops@acmefreight.example",
        },
      });

      // Assert
      expect(duplicate.status()).toBe(409);
      const body = await duplicate.json();
      expect(body.error.code).toBe("vendor_name_taken");
    },
  );
});
